 91	// Zone memory auto-allocation function that allocates the zone size
 92	// by trying progressively smaller zone sizes until one is found that
 93	// works.
 94	
 95	static byte *AutoAllocMemory(int *size, int default_ram, int min_ram)
 96	{
 97	    byte *zonemem;
 98	
 99	    // Allocate the zone memory.  This loop tries progressively smaller
100	    // zone sizes until a size is found that can be allocated.
101	    // If we used the -mb command line parameter, only the parameter
102	    // provided is accepted.
103	
104	    zonemem = NULL;
105	
106	    while (zonemem == NULL)
107	    {
108	        // We need a reasonable minimum amount of RAM to start.
109	
110	        if (default_ram < min_ram)
111	        {
112	            I_Error("Unable to allocate %i MiB of RAM for zone", default_ram);
113	        }
114	
115	        // Try to allocate the zone memory.
116	
117	        *size = default_ram * 1024 * 1024;
118	
119	        zonemem = malloc(*size);
120	
121	        // Failed to allocate?  Reduce zone size until we reach a size
122	        // that is acceptable.
123	
124	        if (zonemem == NULL)
125	        {
126	            default_ram -= 1;
127	        }
128	    }
129	
130	    return zonemem;
131	}
132	
133	byte *I_ZoneBase (int *size)
134	{
135	    byte *zonemem;
136	    int min_ram, default_ram;
137	    int p;
138	
139	    //!
140	    // @arg <mb>
141	    //
142	    // Specify the heap size, in MiB (default 16).
143	    //
144	
145	    p = M_CheckParmWithArgs("-mb", 1);
146	
147	    if (p > 0)
148	    {
149	        default_ram = atoi(myargv[p+1]);
150	        min_ram = default_ram;
151	    }
152	    else
153	    {
154	        default_ram = DEFAULT_RAM;
155	        min_ram = MIN_RAM;
156	    }
157	
158	    zonemem = AutoAllocMemory(size, default_ram, min_ram);
159	
160	    printf("zone memory: %p, %x allocated for zone\n", 
161	           zonemem, *size);
162	
163	    return zonemem;
164	}
