321	// Open a native error box with a message using zenity
322	
323	static int ZenityErrorBox(char *message)
324	{
325	    int result;
326	    char *escaped_message;
327	    char *errorboxpath;
328	    static size_t errorboxpath_size;
329	
330	    if (!ZenityAvailable())
331	    {
332	        return 0;
333	    }
334	
335	    escaped_message = EscapeShellString(message);
336	
337	    errorboxpath_size = strlen(ZENITY_BINARY) + strlen(escaped_message) + 19;
338	    errorboxpath = malloc(errorboxpath_size);
339	    M_snprintf(errorboxpath, errorboxpath_size, "%s --error --text=%s",
340	               ZENITY_BINARY, escaped_message);
341	
342	    result = system(errorboxpath);
343	
344	    free(errorboxpath);
345	    free(escaped_message);
346	
347	    return result;
348	}
