357	static boolean already_quitting = false;
358	
359	void I_Error (char *error, ...)
360	{
361	    char msgbuf[512];
362	    va_list argptr;
363	    atexit_listentry_t *entry;
364	    boolean exit_gui_popup;
365	
366	    if (already_quitting)
367	    {
368	        fprintf(stderr, "Warning: recursive call to I_Error detected.\n");
369	#if ORIGCODE
370	        exit(-1);
371	#endif
372	    }
373	    else
374	    {
375	        already_quitting = true;
376	    }
377	
378	    // Message first.
379	    va_start(argptr, error);
380	    //fprintf(stderr, "\nError: ");
381	    vfprintf(stderr, error, argptr);
382	    fprintf(stderr, "\n\n");
383	    va_end(argptr);
384	    fflush(stderr);
385	
386	    // Write a copy of the message into buffer.
387	    va_start(argptr, error);
388	    memset(msgbuf, 0, sizeof(msgbuf));
389	    M_vsnprintf(msgbuf, sizeof(msgbuf), error, argptr);
390	    va_end(argptr);
391	
392	    // Shutdown. Here might be other errors.
393	
394	    entry = exit_funcs;
395	
396	    while (entry != NULL)
397	    {
398	        if (entry->run_on_error)
399	        {
400	            entry->func();
401	        }
402	
403	        entry = entry->next;
404	    }
405	
406	    exit_gui_popup = !M_ParmExists("-nogui");
407	
408	    // Pop up a GUI dialog box to show the error message, if the
409	    // game was not run from the console (and the user will
410	    // therefore be unable to otherwise see the message).
411	    if (exit_gui_popup && !I_ConsoleStdout())
412	#ifdef _WIN32
413	    {
414	        wchar_t wmsgbuf[512];
415	
416	        MultiByteToWideChar(CP_ACP, 0,
417	                            msgbuf, strlen(msgbuf) + 1,
418	                            wmsgbuf, sizeof(wmsgbuf));
419	
420	        MessageBoxW(NULL, wmsgbuf, L"", MB_OK);
421	    }
422	#elif defined(__MACOSX__)
423	    {
424	        CFStringRef message;
425		int i;
426	
427		// The CoreFoundation message box wraps text lines, so replace
428		// newline characters with spaces so that multiline messages
429		// are continuous.
430	
431		for (i = 0; msgbuf[i] != '\0'; ++i)
432	        {
433	            if (msgbuf[i] == '\n')
434	            {
435	                msgbuf[i] = ' ';
436	            }
437	        }
438	
439	        message = CFStringCreateWithCString(NULL, msgbuf,
440	                                            kCFStringEncodingUTF8);
441	
442	        CFUserNotificationDisplayNotice(0,
443	                                        kCFUserNotificationCautionAlertLevel,
444	                                        NULL,
445	                                        NULL,
446	                                        NULL,
447	                                        CFSTR(PACKAGE_STRING),
448	                                        message,
449	                                        NULL);
450	    }
451	#elif defined(__DJGPP__)
452	    {
453	        printf("%s\n", msgbuf);
454	        exit(-1);
455	    }
456	
457	#else
458	    {
459	        ZenityErrorBox(msgbuf);
460	    }
461	#endif
462	
463	    // abort();
464	#if ORIGCODE
465	    SDL_Quit();
466	
467	    exit(-1);
468	#else
469	    while (true)
470	    {
471	    }
472	#endif
473	}
