504	
505	boolean I_GetMemoryValue(unsigned int offset, void *value, int size)
506	{
507	    static boolean firsttime = true;
508	
509	    if (firsttime)
510	    {
511	        int p, i, val;
512	
513	        firsttime = false;
514	        i = 0;
515	
516	        //!
517	        // @category compat
518	        // @arg <version>
519	        //
520	        // Specify DOS version to emulate for NULL pointer dereference
521	        // emulation.  Supported versions are: dos622, dos71, dosbox.
522	        // The default is to emulate DOS 7.1 (Windows 98).
523	        //
524	
525	        p = M_CheckParmWithArgs("-setmem", 1);
526	
527	        if (p > 0)
528	        {
529	            if (!strcasecmp(myargv[p + 1], "dos622"))
530	            {
531	                dos_mem_dump = mem_dump_dos622;
532	            }
533	            if (!strcasecmp(myargv[p + 1], "dos71"))
534	            {
535	                dos_mem_dump = mem_dump_win98;
536	            }
537	            else if (!strcasecmp(myargv[p + 1], "dosbox"))
538	            {
539	                dos_mem_dump = mem_dump_dosbox;
540	            }
541	            else
542	            {
543	                for (i = 0; i < DOS_MEM_DUMP_SIZE; ++i)
544	                {
545	                    ++p;
546	
547	                    if (p >= myargc || myargv[p][0] == '-')
548	                    {
549	                        break;
550	                    }
551	
552	                    M_StrToInt(myargv[p], &val);
553	                    mem_dump_custom[i++] = (unsigned char) val;
554	                }
555	
556	                dos_mem_dump = mem_dump_custom;
557	            }
558	        }
559	    }
560	
561	    switch (size)
562	    {
563	    case 1:
564	        *((unsigned char *) value) = dos_mem_dump[offset];
565	        return true;
566	    case 2:
567	        *((unsigned short *) value) = dos_mem_dump[offset]
568	                                    | (dos_mem_dump[offset + 1] << 8);
569	        return true;
570	    case 4:
571	        *((unsigned int *) value) = dos_mem_dump[offset]
572	                                  | (dos_mem_dump[offset + 1] << 8)
573	                                  | (dos_mem_dump[offset + 2] << 16)
574	                                  | (dos_mem_dump[offset + 3] << 24);
575	        return true;
576	    }
577	
578	    return false;
579	}
