43	    }
44	
45	    // Create a new stdc_wad_file_t to hold the file handle.
46	
47	    result = Z_Malloc(sizeof(stdc_wad_file_t), PU_STATIC, 0);
48	    result->wad.file_class = &stdc_wad_file;
49	    result->wad.mapped = NULL;
50	    result->wad.length = M_FileLength(fstream);
51	    result->fstream = fstream;
52	
53	    return &result->wad;
54	}
