 43	static unsigned char convertToDoomKey(unsigned char scancode)
 44	{
 45	    unsigned char key = 0;
 46	
 47	    switch (scancode)
 48	    {
 49	    case 0x9C:
 50	    case 0x1C:
 51	        key = KEY_ENTER;
 52	        break;
 53	    case 0x01:
 54	        key = KEY_ESCAPE;
 55	        break;
 56	    case 0xCB:
 57	    case 0x4B:
 58	        key = KEY_LEFTARROW;
 59	        break;
 60	    case 0xCD:
 61	    case 0x4D:
 62	        key = KEY_RIGHTARROW;
 63	        break;
 64	    case 0xC8:
 65	    case 0x48:
 66	        key = KEY_UPARROW;
 67	        break;
 68	    case 0xD0:
 69	    case 0x50:
 70	        key = KEY_DOWNARROW;
 71	        break;
 72	    case 0x1D:
 73	        key = KEY_FIRE;
 74	        break;
 75	    case 0x39:
 76	        key = KEY_USE;
 77	        break;
 78	    case 0x2A:
 79	    case 0x36:
 80	        key = KEY_RSHIFT;
 81	        break;
 82	    case 0x15:
 83	        key = 'y';
 84	        break;
 85	    default:
 86	        break;
 87	    }
 88	
 89	    return key;
 90	}
