 92	static void addKeyToQueue(int pressed, unsigned char keyCode)
 93	{
 94		//printf("key hex %x decimal %d\n", keyCode, keyCode);
 95	
 96	        unsigned char key = convertToDoomKey(keyCode);
 97	
 98	        unsigned short keyData = (pressed << 8) | key;
 99	
100	        s_KeyQueue[s_KeyQueueWriteIndex] = keyData;
101	        s_KeyQueueWriteIndex++;
102	        s_KeyQueueWriteIndex %= KEYQUEUE_SIZE;
