 64	// Check if a file exists
 65	
 66	boolean M_FileExists(char *filename)
 67	{
 68	    FILE *fstream;
 69	
 70	    fstream = fopen(filename, "r");
 71	
 72	    if (fstream != NULL)
 73	    {
 74	        fclose(fstream);
 75	        return true;
 76	    }
 77	    else
 78	    {
 79	        // If we can't open because the file is a directory, the 
 80	        // "file" exists at least!
 81	
 82	        return errno == EISDIR;
 83	    }
 84	}
