370	// Safe string copy function that works like OpenBSD's strlcpy().
371	// Returns true if the string was not truncated.
372	
373	boolean M_StringCopy(char *dest, const char *src, size_t dest_size)
374	{
375	    size_t len;
376	
377	    if (dest_size >= 1)
378	    {
379	        dest[dest_size - 1] = '\0';
380	        strncpy(dest, src, dest_size - 1);
381	    }
382	    else
383	    {
384	        return false;
385	    }
386	
387	    len = strlen(dest);
388	    return src[len] == '\0';
389	}
