391	// Safe string concat function that works like OpenBSD's strlcat().
392	// Returns true if string not truncated.
393	
394	boolean M_StringConcat(char *dest, const char *src, size_t dest_size)
395	{
396	    size_t offset;
397	
398	    offset = strlen(dest);
399	    if (offset > dest_size)
400	    {
401	        offset = dest_size;
402	    }
403	
404	    return M_StringCopy(dest + offset, src, dest_size - offset);
405	}
