415	// Returns true if 's' ends with the specified suffix.
416	
417	boolean M_StringEndsWith(const char *s, const char *suffix)
418	{
419	    return strlen(s) >= strlen(suffix)
420	        && strcmp(s + strlen(s) - strlen(suffix), suffix) == 0;
421	}
