423	// Return a newly-malloced string with all the strings given as arguments
424	// concatenated together.
425	
426	char *M_StringJoin(const char *s, ...)
427	{
428	    char *result;
429	    const char *v;
430	    va_list args;
431	    size_t result_len;
432	
433	    result_len = strlen(s) + 1;
434	
435	    va_start(args, s);
436	    for (;;)
437	    {
438	        v = va_arg(args, const char *);
439	        if (v == NULL)
440	        {
441	            break;
442	        }
443	
444	        result_len += strlen(v);
445	    }
446	    va_end(args);
447	
448	    result = malloc(result_len);
449	
450	    if (result == NULL)
451	    {
452	        I_Error("M_StringJoin: Failed to allocate new string.");
453	        return NULL;
454	    }
455	
456	    M_StringCopy(result, s, result_len);
457	
458	    va_start(args, s);
459	    for (;;)
460	    {
461	        v = va_arg(args, const char *);
462	        if (v == NULL)
463	        {
464	            break;
465	        }
466	
467	        M_StringConcat(result, v, result_len);
468	    }
469	    va_end(args);
470	
471	    return result;
472	}
